"""
picozero/wifi.py
WiFi class for Raspberry Pi Pico W / Pico 2 W — wraps the network module
in a simple picozero-style API compatible with espzero.WiFi.
"""


class WiFi:
    """
    Wraps Raspberry Pi Pico W Wi-Fi (station & AP modes) and lightweight HTTP
    web serving in a simple, intuitive interface.

    Usage::

        from picozero import WiFi
        wifi = WiFi()
        ip = wifi.connect("MySSID", "password")
        print("Connected:", ip)
    """

    def __init__(self):
        import network

        self._sta = network.WLAN(network.STA_IF)
        try:
            self._ap = network.WLAN(network.AP_IF)
        except Exception:
            self._ap = None

    def connect(self, ssid, password, timeout=20):
        """
        Connect to the given access point.

        Blocks until connected (up to *timeout* seconds, default 20) then returns the
        assigned IP address string. Raises ``OSError`` on timeout.

        :param str ssid: Network name (SSID). Note: Pico W requires 2.4GHz Wi-Fi.
        :param str password: Network password.
        :param int timeout: Maximum seconds to wait for connection. Default 20.
        :returns: IP address string.
        :raises OSError: If the connection times out.
        """
        import time

        if not self._sta.active():
            self._sta.active(True)
            time.sleep(0.2)

        try:
            self._sta.disconnect()
            time.sleep(0.1)
        except Exception:
            pass

        print("[picozero] Connecting to WiFi '{}' (2.4GHz)...".format(ssid), end="")
        self._sta.connect(ssid, password)
        start = time.time()
        last_dot = start
        while not self._sta.isconnected():
            now = time.time()
            if now - last_dot >= 1.0:
                print(".", end="")
                last_dot = now

            if now - start > timeout:
                print(" Failed!")
                status_msg = ""
                try:
                    stat = self._sta.status()
                    import network

                    if (
                        hasattr(network, "STAT_WRONG_PASSWORD")
                        and stat == network.STAT_WRONG_PASSWORD
                    ):
                        status_msg = " (Reason: Wrong password)"
                    elif (
                        hasattr(network, "STAT_NO_AP_FOUND")
                        and stat == network.STAT_NO_AP_FOUND
                    ):
                        status_msg = (
                            " (Reason: SSID not found - ensure it is 2.4GHz, not 5GHz)"
                        )
                except Exception:
                    pass
                raise OSError(
                    "[picozero] WiFi connection timed out ({}s).{}".format(
                        timeout, status_msg
                    )
                )
            time.sleep(0.1)

        print(" Connected!")
        ip = self._sta.ifconfig()[0]
        print("[picozero] WiFi connected. IP:", ip)
        return ip

    def disconnect(self):
        """Disconnect from the current access point."""
        self._sta.disconnect()

    def start_ap(self, ssid="PicoW-AP", password=None, channel=1):
        """
        Start an Access Point (hotspot) on the Pico W / Pico 2 W.

        :param str ssid: Hotspot network name (SSID).
        :param str password: Optional WPA2 password (must be >= 8 chars if provided).
                             If ``None`` or ``""``, starts an open hotspot.
        :param int channel: Wi-Fi channel (default 1).
        :returns: AP IP address string (typically ``"192.168.4.1"``).
        """
        import network
        import time

        if self._ap is None:
            self._ap = network.WLAN(network.AP_IF)

        if password:
            try:
                self._ap.config(essid=ssid, password=password, channel=channel)
            except Exception:
                self._ap.config(essid=ssid, password=password)
        else:
            # RP2040/RP2350 MicroPython uses security=0 (CYW43) or authmode=0 for open AP
            try:
                self._ap.config(essid=ssid, security=0, channel=channel)
            except Exception:
                try:
                    auth = getattr(network, "AUTH_OPEN", 0)
                    self._ap.config(essid=ssid, authmode=auth, channel=channel)
                except Exception:
                    self._ap.config(essid=ssid)

        if not self._ap.active():
            self._ap.active(True)
        while not self._ap.active():
            time.sleep(0.05)

        ip = self._ap.ifconfig()[0]
        print("[picozero] AP mode started: SSID='{}', IP={}".format(ssid, ip))
        return ip

    def stop_ap(self):
        """Deactivate the Access Point (hotspot) interface."""
        if self._ap is not None:
            self._ap.active(False)

    def scan(self):
        """
        Scan for nearby access points.

        :returns: List of tuples ``(ssid, bssid, channel, rssi, authmode, hidden)``.
        """
        self._sta.active(True)
        return self._sta.scan()

    @property
    def is_connected(self):
        """``True`` if currently connected to an access point."""
        return self._sta.isconnected()

    @property
    def ip(self):
        """Current IP address (STA if connected, else AP if active, else ``None``)."""
        if self.is_connected:
            return self._sta.ifconfig()[0]
        if self._ap is not None and self._ap.active():
            return self._ap.ifconfig()[0]
        return None

    @property
    def ifconfig(self):
        """Full interface config tuple ``(ip, mask, gateway, dns)``."""
        if not self.is_connected and self._ap is not None and self._ap.active():
            return self._ap.ifconfig()
        return self._sta.ifconfig()

    @staticmethod
    def _parse_http_request(first_line):
        parts = first_line.split(" ") if first_line else []
        raw_target = parts[1] if len(parts) > 1 else "/"
        if "?" in raw_target:
            path, query = raw_target.split("?", 1)
        else:
            path, query = raw_target, ""
        params = {}
        if query:
            for item in query.split("&"):
                if "=" in item:
                    k, v = item.split("=", 1)
                    params[k] = v.replace("%20", " ").replace("+", " ")
        return path, params

    @staticmethod
    def _build_http_response(body, content_type=None):
        if isinstance(body, (dict, list)):
            import json

            payload = json.dumps(body).encode("utf-8")
            ctype = content_type or "application/json; charset=utf-8"
        elif isinstance(body, (bytes, bytearray)):
            payload = bytes(body)
            ctype = content_type or "application/octet-stream"
        else:
            text = "" if body is None else str(body)
            head = text.lstrip()[:15].lower()
            is_html = (
                head.startswith("<!doctype")
                or head.startswith("<html")
                or head.startswith("<body")
                or head.startswith("<h")
                or head.startswith("<div")
            )
            ctype = content_type or (
                "text/html; charset=utf-8" if is_html else "text/plain; charset=utf-8"
            )
            payload = text.encode("utf-8")

        header = (
            "HTTP/1.1 200 OK\r\n"
            "Content-Type: {}\r\n"
            "Access-Control-Allow-Origin: *\r\n"
            "Connection: close\r\n\r\n"
        ).format(ctype).encode("utf-8")
        return header + payload

    @staticmethod
    def _invoke_handler(handler, path, params):
        try:
            return handler(path, params)
        except TypeError:
            return handler(path)

    def serve(self, handler, port=80, host="0.0.0.0"):
        """
        Run a lightweight blocking HTTP web server on *port* (default 80).

        For each incoming request, calls ``handler(path, params)`` (or ``handler(path)``)
        where ``path`` is the URL path (e.g. ``"/on"``) and ``params`` is a dict of query
        parameters (e.g. ``{"dir": "F", "spd": "70"}``).

        The return value of *handler* is automatically sent with an HTTP 200 header:
        - ``str`` starting with HTML tags -> ``text/html; charset=utf-8``
        - ``dict`` or ``list`` -> ``application/json; charset=utf-8``
        - any other ``str`` -> ``text/plain; charset=utf-8``
        """
        import socket

        srv = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        srv.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        srv.bind((host, port))
        srv.listen(4)
        print(
            "[picozero] Web server listening on http://{}:{}/".format(
                self.ip or host, port
            )
        )
        try:
            while True:
                client, _ = srv.accept()
                try:
                    client.settimeout(2.0)
                    req = client.recv(1024).decode("utf-8", "ignore")
                    first = req.split("\r\n", 1)[0] if req else ""
                    path, params = self._parse_http_request(first)
                    body = self._invoke_handler(handler, path, params)
                    client.sendall(self._build_http_response(body))
                except Exception as e:
                    print("[picozero] HTTP handler error:", e)
                finally:
                    client.close()
        finally:
            srv.close()

    async def async_serve(self, handler, port=80, host="0.0.0.0"):
        """
        Run a lightweight non-blocking ``asyncio`` HTTP web server on *port* (default 80).

        Can be passed directly to ``await asyncio.gather(wifi.async_serve(handler), ...)``.
        *handler* may be a regular function or an ``async def`` coroutine taking
        ``(path, params)`` (or ``(path,)``).
        """
        try:
            import asyncio
        except ImportError:
            import uasyncio as asyncio

        async def _client_cb(reader, writer):
            try:
                req_line = (await reader.readline()).decode("utf-8", "ignore")
                while True:
                    hdr = await reader.readline()
                    if not hdr or hdr == b"\r\n":
                        break
                path, params = self._parse_http_request(req_line.strip())
                res = self._invoke_handler(handler, path, params)
                if hasattr(res, "send"):
                    res = await res
                writer.write(self._build_http_response(res))
                await writer.drain()
            except Exception as e:
                print("[picozero] Async HTTP error:", e)
            finally:
                try:
                    writer.close()
                    await writer.wait_closed()
                except Exception:
                    pass

        server = await asyncio.start_server(_client_cb, host, port)
        print(
            "[picozero] Async web server listening on http://{}:{}/".format(
                self.ip or host, port
            )
        )
        await server.wait_closed()
